(* [comment removed for export] *)
Theorem node_mmap2_sound_OBL : forall SEGS scfg A nx0 LIMIT SINV argH FS0,
  sc_alloc scfg = false ->                                                                            (* [comment removed for export] *)
  wx_segs_nowrap SEGS ->
  (forall a : word, in_hull A (bv_unsigned a) = false -> find_segment SEGS (bv_unsigned a) 1 = None) ->
  res_len_ok SEGS A ->
  Forall (fun iv => img_lo A <= bv_unsigned (fst iv) /\ bv_unsigned (fst iv) + bv_unsigned (snd iv) <= img_hi A) (segments_reserved SEGS) ->
  hull_ok A -> shadow_ok A ->
  (forall E (a : word), argH E a = true -> CEIL <= bv_unsigned a /\ uE E e_sp0 <= bv_unsigned a) ->   (* [comment removed for export] *)
